int b1=2, b2=3, led=13, buzzer=8; int prev=-1;
void setup(){pinMode(b1,INPUT);pinMode(b2,INPUT);pinMode(led,OUTPUT);pinMode(buzzer,OUTPUT);Serial.begin(9600);}
void loop(){
  int w=(digitalRead(b1)?1:0)+(digitalRead(b2)?2:0); // 1=sakrash 2=emaklash 3=idishga sol
  if(w!=prev){ Serial.print("BTN:");Serial.println(w); prev=w; }
  digitalWrite(led, w>0);
  if(w>0) tone(buzzer, w==3?1400:900, 25);
  delay(15);
}
